from pathlib import Path
import json
root=Path(__file__).resolve().parent
old=root.parent/'fantasy-kit-v03'
assets=json.loads((root/'inventory.json').read_text(encoding='utf-8'))['assets']
specials={
'hero-classic':'a lunging sword thrust with shield braced', 'hero-gothic':'a two-handed overhead dark sword cleave', 'hero-kawaii':'a spinning star-charged sword strike', 'hero-persian':'a low acrobatic scimitar slash',
'companion-brasa':'a heavy hammer slam into the ground','companion-luma':'kneel and raise the staff to grow curling healing vines',
'enemy-brass-sentry':'body leans forward and shield-edged arm stabs','enemy-copper-crab':'large pincer opens, arm thrusts, pincer closes', 'enemy-root-warden':'wooden arm extends into a root spear','enemy-sporeling':'cap compresses then opens to expel spores','enemy-storm-sentinel':'spear overhead windup then deep forward thrust','enemy-storm-wisp':'entire lightning body coils and uncoils into a bolt',
'boss-04-furnace-executioner':'furnace chest opens and great cleaver smashes down','boss-05-living-cathedral':'all architectural legs bend and the enormous front claw slams','boss-06-stained-glass-hydra':'multiple independent necks recoil then three heads bite forward','boss-07-bell-seraph':'pipe-organ wings fold then fan wide while claws slash','boss-08-moon-devourer':'crescent maw opens, segmented body coils, huge claws snap','boss-rebocador':'massive hammer lifts overhead and crashes down','boss-storm-archon':'spear and cape sweep while a lightning arc is released','boss-sylvan-heart':'root arms raise overhead then smash with growing vines'}
titles={'hero-classic':'Cavaleiro clássico','hero-gothic':'Cavaleiro sombrio','hero-kawaii':'Cavaleiro estelar','hero-persian':'Andarilho persa','companion-brasa':'Brasa','companion-luma':'Luma','enemy-brass-sentry':'Vigia de latão','enemy-copper-crab':'Caranguejo de cobre','enemy-root-warden':'Guardião de raízes','enemy-sporeling':'Esporídeo','enemy-storm-sentinel':'Sentinela da tempestade','enemy-storm-wisp':'Centelha','boss-04-furnace-executioner':'Carrasco das Mil Forjas','boss-05-living-cathedral':'Catedral Faminta','boss-06-stained-glass-hydra':'Hidra dos Juramentos','boss-07-bell-seraph':'Serafim do Último Sino','boss-08-moon-devourer':'Devorador de Luas','boss-rebocador':'Rebocador','boss-storm-archon':'Arconte da Tempestade','boss-sylvan-heart':'Coração Silvestre','npc-artisan':'Artesã','npc-cartographer':'Cartógrafo','npc-collector':'Colecionadora','world-boss-09-azhor':'AZHOR'}
base='''Create a production pixel-art animation sprite sheet of the EXACT character in the reference. Reference is identity and material design: preserve silhouette, equipment, body parts, colors and proportions. Detailed silver-blue metal, warm golden trim, crisp clustered pixels matching the reference. Fixed camera and facing direction throughout. TRUE distinct whole-body drawings, changed joint angles and silhouettes, no rigid cutout rotation, no duplicated static pose. Every cell contains one complete isolated pose, not pieces. EXACTLY FOUR COLUMNS and FOUR ROWS, 16 equal square cells, read left-to-right. One animation per row, four sequential frames each. Transparent background alpha 0. No floor, text, numbers, grid lines, frames or scenery. Keep the whole figure INCLUDING effects within middle 65% width and 72% height of each cell, 15% clear gutters. SAME body scale across ALL 16 poses, feet on baseline 85%; a fallen corpse remains low and horizontal, never scaled up to fill the cell. No cropping of weapons or effects. Each row is a separate action; do not mix actions between rows. Four columns within each row correspond to four successive timestamps. '''
jobs=[]
for a in assets:
    if a['id'] not in specials and a['category']!='npcs':continue
    ident=a['id']; title=titles[ident]; ref=str(old/a['png'])
    if a['category']=='npcs':
        work={'npc-artisan':'raises hammer, strikes anvil, recoils hammer, checks forged piece','npc-cartographer':'unrolls map, traces route with finger, writes with quill, holds map open','npc-collector':'lifts lantern, examines a small relic, polishes relic, offers it forward'}[ident]
        batches=[('daily',['idle','walk','work','greet'],f'Row 1 IDLE: relaxed, inhale shoulders rise, look sideways, relaxed. Row 2 WALK in place: left contact, left passing, right contact, right passing; clear alternating legs. Row 3 WORK: {work}. Row 4 GREET: hand low, arm rises, open hand waves with bent elbow, hand lowers.')]
    else:
        move='alternating legs and flexing knees' if 'wisp' not in ident and 'seraph' not in ident else 'alternating curled and extended airborne limbs'
        batches=[('motion',['idle','walk','hurt','death'],f'Row 1 IDLE: resting, inhale with shoulders lifted, exhale and head turns slightly, rest again; subtle cloth movement. Row 2 WALK cycle in place: left contact, left passing, right contact, right passing, {move}; do not translate the entire figure. Row 3 HURT: brace, recoil back with bent knees and head down, recover balance, ready. Row 4 DEATH: stagger, collapse onto knees with weapon lowered, fall horizontally onto side, lifeless collapsed corpse. Last two death frames must be unmistakably horizontal and low, no upright standing death.'),('combat',['attack','special','defense','rage' if a['category']=='bosses' else 'victory'],f'Row 1 ATTACK: anticipation winding up, full extension at strike, follow-through, ready. The action is {specials[ident]}. Row 2 SPECIAL: deep charge crouch, arms/head lift to concentrate energy, fully extended body releases a strong magical attack using this character\'s weapon or anatomy, exhausted recovery. Row 3 DEFENSE: ready, lower center of gravity and cross weapon/shield/arms in front of torso, brace under impact with knees deeply flexed, rise. Row 4 CELEBRATION or BOSS RAGE: low crouch, stand high with arms raised, powerful roar or victorious weapon lift, return. No new creatures, no extra weapons, no extra limbs.')]
    for batch,states,story in batches:
        jobs.append(dict(id=ident+'--'+batch,actor=ident,title=title,category=a['category'],states=states,columns=4,rows=4,width=192 if a['category']=='bosses' else 128,height=192 if a['category']=='bosses' else 128,reference=ref,prompt=base+story))
(root/'generation-jobs.json').write_text(json.dumps(jobs,ensure_ascii=False,indent=2),encoding='utf-8')
(root/'titles.json').write_text(json.dumps(titles,ensure_ascii=False,indent=2),encoding='utf-8')
print(len(jobs),'pose sheets planned')
